const request = require('supertest');
const app = require('./app');

describe('POST /users validation', () => {
  it('should reject requests with missing name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({})
      .expect(400);

    expect(response.body.error).toBe('Validation failed');
    expect(response.body.message).toBe('Missing required field: name');
  });

  it('should reject requests with null name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: null })
      .expect(400);

    expect(response.body.error).toBe('Validation failed');
    expect(response.body.message).toBe('Missing required field: name');
  });

  it('should reject requests with non-string name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 123 })
      .expect(400);

    expect(response.body.error).toBe('Validation failed');
    expect(response.body.message).toBe('Field name must be a string');
  });

  it('should accept valid string name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 'John Doe' })
      .expect(201);

    expect(response.body.name).toBe('John Doe');
    expect(response.body.id).toBeDefined();
    expect(response.body.email).toBe('john.doe@example.com');
  });

  it('should trim whitespace from name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '  Jane Smith  ' })
      .expect(201);

    expect(response.body.name).toBe('Jane Smith');
  });
});

// Simple validation logic verification without external dependencies
function validateName(name) {
  // Validate that name exists and is a string
  if (name === undefined || name === null) {
    return { 
      error: 'Validation failed', 
      message: 'Missing required field: name' 
    };
  }

  if (typeof name !== 'string') {
    return { 
      error: 'Validation failed', 
      message: 'Field name must be a string' 
    };
  }

  // If validation passes
  return { 
    success: true, 
    name: name.trim() 
  };
}

// Test cases
console.log('Testing validation logic:');

// Test 1: Missing name
const result1 = validateName(undefined);
console.log('Test 1 - Undefined name:', result1);

// Test 2: Null name
const result2 = validateName(null);
console.log('Test 2 - Null name:', result2);

// Test 3: Non-string name
const result3 = validateName(123);
console.log('Test 3 - Number name:', result3);

// Test 4: Valid string
const result4 = validateName('John Doe');
console.log('Test 4 - Valid name:', result4);

// Test 5: String with whitespace
const result5 = validateName('  Jane Smith  ');
console.log('Test 5 - Whitespace name:', result5);

// Expected results:
// Test 1: Should fail with missing field message
// Test 2: Should fail with missing field message  
// Test 3: Should fail with must be string message
// Test 4: Should succeed with trimmed name
// Test 5: Should succeed with trimmed name

